import{_ as a,a0 as l,w as r,s as p,I as t,x as s,a1 as o,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"什麼是殭屍進程，如何找到並殺掉殭屍進程？ | LCTT x X-CMD","titleTemplate":false,"description":"什麼是殭屍進程，如何找到並殺掉殭屍進程？ | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什麼是殭屍進程，如何找到並殺掉殭屍進程？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什麼是殭屍進程，如何找到並殺掉殭屍進程？ | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171211 What Are Zombie Processes And How To Find & Kill Zombie Processes-","title":"什麼是殭屍進程，如何找到並殺掉殭屍進程？","tag":"201712","desc":""},"relativePath":"201712/20171211 What Are Zombie Processes And How To Find & Kill Zombie Processes-.md","filePath":"[post].md"}'),u={name:"201712/20171211 What Are Zombie Processes And How To Find & Kill Zombie Processes-.md"};function m(b,e,h,g,f,w){const i=l("Link");return r(),p("div",null,[e[15]||(e[15]=t("h1",{id:"什麼是殭屍進程-如何找到並殺掉殭屍進程",tabindex:"-1"},[s("什麼是殭屍進程，如何找到並殺掉殭屍進程？ "),t("a",{class:"header-anchor",href:"#什麼是殭屍進程-如何找到並殺掉殭屍進程","aria-label":"Permalink to “什麼是殭屍進程，如何找到並殺掉殭屍進程？”"},"​")],-1)),t("p",null,[o(i,{href:"http://www.linuxandubuntu.com/home/what-are-zombie-processes-and-how-to-find-kill-zombie-processes"},{default:n(()=>[...e[0]||(e[0]=[t("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/what-are-the-zombie-processes_orig.jpg",alt:"What Are Zombie Processes And How To Find & Kill Zombie Processes？"},null,-1)])]),_:1})]),e[16]||(e[16]=t("p",null,[s("如果你經常使用 Linux，你應該遇到這個術語“"),t("ruby",null,[s("殭屍進程"),t("rt",null,"Zombie Processes")]),s("”。 那麼什麼是殭屍進程？ 它們是怎麼產生的？ 它們是否對系統有害？ 我要怎樣殺掉這些進程？ 下面將會回答這些問題。")],-1)),e[17]||(e[17]=t("h3",{id:"什麼是殭屍進程",tabindex:"-1"},[s("什麼是殭屍進程？ "),t("a",{class:"header-anchor",href:"#什麼是殭屍進程","aria-label":"Permalink to “什麼是殭屍進程？”"},"​")],-1)),e[18]||(e[18]=t("p",null,"我們都知道進程的工作原理。我們啓動一個程序，開始我們的任務，然後等任務結束了，我們就停止這個進程。 進程停止後， 該進程就會從進程表中移除。",-1)),e[19]||(e[19]=t("p",null,[s("你可以通過 "),t("code",null,"System-Monitor"),s(" 查看當前進程。")],-1)),t("p",null,[o(i,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/linux-check-zombie-processes_orig.jpg"},{default:n(()=>[...e[1]||(e[1]=[t("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/linux-check-zombie-processes_orig.jpg",alt:""},null,-1)])]),_:1})]),e[20]||(e[20]=d('<p>但是，有時候有些程序即使執行完了也依然留在進程表中。</p><p>那麼，這些完成了生命週期但卻依然留在進程表中的進程，我們稱之為 “殭屍進程”。</p><h3 id="它們是如何產生的" tabindex="-1">它們是如何產生的？ <a class="header-anchor" href="#它們是如何產生的" aria-label="Permalink to “它們是如何產生的？”">​</a></h3><p>當你運行一個程序時，它會產生一個父進程以及很多子進程。 所有這些子進程都會消耗內核分配給它們的內存和 CPU 資源。</p><p>這些子進程完成執行後會發送一個 Exit 信號然後死掉。這個 Exit 信號需要被父進程所讀取。父進程需要隨後調用 <code>wait</code> 命令來讀取子進程的退出狀態，並將子進程從進程表中移除。</p><p>若父進程正確第讀取了子進程的 Exit 信號，則子進程會從進程表中刪掉。</p><p>但若父進程未能讀取到子進程的 Exit 信號，則這個子進程雖然完成執行處於死亡的狀態，但也不會從進程表中刪掉。</p><h3 id="殭屍進程對系統有害嗎" tabindex="-1">殭屍進程對系統有害嗎？ <a class="header-anchor" href="#殭屍進程對系統有害嗎" aria-label="Permalink to “殭屍進程對系統有害嗎？”">​</a></h3><p><strong>不會</strong>。由於殭屍進程並不做任何事情， 不會使用任何資源也不會影響其它進程， 因此存在殭屍進程也沒什麼壞處。 不過由於進程表中的退出狀態以及其它一些進程信息也是存儲在內存中的，因此存在太多殭屍進程有時也會是一些問題。</p><p><strong>你可以想像成這樣：</strong></p><p>“你是一家建築公司的老闆。你每天根據工人們的工作量來支付工資。 有一個工人每天來到施工現場，就坐在那裏， 你不用付錢， 他也不做任何工作。 他只是每天都來然後呆坐在那，僅此而已！”</p><p>這個工人就是殭屍進程的一個活生生的例子。<strong>但是</strong>， 如果你有很多殭屍工人， 你的建設工地就會很擁堵從而讓那些正常的工人難以工作。</p><h3 id="那麼如何找出殭屍進程呢" tabindex="-1">那麼如何找出殭屍進程呢？ <a class="header-anchor" href="#那麼如何找出殭屍進程呢" aria-label="Permalink to “那麼如何找出殭屍進程呢？”">​</a></h3><p>打開終端並輸入下面命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ps aux | grep Z</span></span></code></pre></div><p>會列出進程表中所有殭屍進程的詳細內容。</p><h3 id="如何殺掉殭屍進程" tabindex="-1">如何殺掉殭屍進程？ <a class="header-anchor" href="#如何殺掉殭屍進程" aria-label="Permalink to “如何殺掉殭屍進程？”">​</a></h3><p>正常情況下我們可以用 <code>SIGKILL</code> 信號來殺死進程，但是殭屍進程已經死了， 你不能殺死已經死掉的東西。 因此你需要輸入的命令應該是</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kill -s SIGCHLD pid</span></span></code></pre></div><p>將這裏的 pid 替換成父進程的進程 id，這樣父進程就會刪除所有以及完成並死掉的子進程了。</p><p><strong>你可以把它想像成：</strong></p><p>&quot;你在道路中間發現一具屍體，於是你聯繫了死者的家屬，隨後他們就會將屍體帶離道路了。&quot;</p><p>不過許多程序寫的不是那麼好，無法刪掉這些子殭屍（否則你一開始也見不到這些殭屍了）。 因此確保刪除子殭屍的唯一方法就是殺掉它們的父進程。</p><hr>',24)),t("p",null,[e[3]||(e[3]=s("via: ",-1)),o(i,{href:"http://www.linuxandubuntu.com/home/what-are-zombie-processes-and-how-to-find-kill-zombie-processes"},{default:n(()=>[...e[2]||(e[2]=[s("http://www.linuxandubuntu.com/home/what-are-zombie-processes-and-how-to-find-kill-zombie-processes",-1)])]),_:1})]),t("p",null,[e[7]||(e[7]=s("作者：",-1)),o(i,{href:"http://www.linuxandubuntu.com"},{default:n(()=>[...e[4]||(e[4]=[s("linuxandubuntu",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),o(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[5]||(e[5]=[s("lujun9972",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[6]||(e[6]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const P=a(u,[["render",m]]);export{T as __pageData,P as default};
